const ticketStyleSheet=document.createElement('style');ticketStyleSheet.textContent=ticketStyles;document.head.append(ticketStyleSheet);
const isLocalFile=!['http:','https:'].includes(location.protocol);
const $=s=>document.querySelector(s),KEY='autobox-v1',types={auto:'Auto',moto:'Moto',camioneta:'Camioneta'},paths={eye:'M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',close:'M6 6l12 12M18 6 6 18',chevronRight:'m9 5 7 7-7 7',chevronLeft:'m15 5-7 7 7 7',chevronDown:'m5 9 7 7 7-7',key:'M14 10a5 5 0 1 0-4 4l-7 7m4-4 2 2m1-5 2 2',qr:'M3 3h6v6H3zM15 3h6v6h-6zM3 15h6v6H3zM15 15h2v2h-2zM19 19h2v2h-2zM13 21v-4m8-4h-4M13 3v4',entrada:'M3 13h18M5 13l2-7h10l2 7M5 13v6m14-6v6M5 17h14M8 16h.01M16 16h.01M3 13v4h2m16-4v4h-2',resumen:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',salida:'M13 3H5v18h8M10 12h12m-4-4 4 4-4 4',historial:'M3 11a9 9 0 1 1 3 8M3 4v7h7m2-4v6l4 2',tickets:'M3 5h18v4a3 3 0 0 0 0 6v4H3v-4a3 3 0 0 0 0-6zM15 5v2m0 3v2m0 3v4',ajustes:'M4 6h16M4 12h16M4 18h16M8 3v6m8 0v6M10 15v6',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',money:'M3 5h18v14H3zM7 9h.01M17 15h.01M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6zM8 12l3 3 5-6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',print:'M7 8V3h10v5M7 17H3V8h18v9h-4M7 13h10v8H7z',moto:'M6 19a4 4 0 1 1 0-8 4 4 0 0 1 0 8M18 19a4 4 0 1 1 0-8 4 4 0 0 1 0 8M6 15l5-8h4l3 8M9 7H6M14 4h3l1 7',camioneta:'M2 8h13v10H2zM15 11h4l3 4v3h-7M6 21a3 3 0 1 0 0-6 3 3 0 0 0 0 6M18 21a3 3 0 1 0 0-6 3 3 0 0 0 0 6',info:'M12 11v6M12 7h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0'};
const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.entrada}"/></svg>`,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=fresh(),storageError='',category='auto',lastEntry=null,filter='all',search='',exitSearch='',historySearch='',historyStatus='all',historyDate='',pendingImport=null,installEvent=null;
try{const stored=localStorage.getItem(KEY);if(stored)state=validate(JSON.parse(stored));}catch(e){storageError=e.name==='SecurityError'?'Este visor no permite guardar datos. Abre el HTML con un navegador que permita JavaScript y almacenamiento local.':'No se pudo leer la información guardada. Descarga el archivo de recuperación en Ajustes antes de importar otra copia.';}
let page=location.hash.slice(1)||'entrada';const navItems=[['resumen','Inicio'],['entrada','Registrar'],['salida','Cobrar'],['ajustes','Ajustes']];
const money=n=>`${esc(state.settings.currency)} ${Number(n||0).toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2})}`,time=t=>new Date(t).toLocaleTimeString('es-PE',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}),date=t=>new Date(t).toLocaleDateString('es-PE',{day:'2-digit',month:'short'}),day=t=>{const d=new Date(t);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;},today=()=>day(Date.now()),inside=()=>state.visits.filter(v=>v.exit==null),duration=m=>m<60?`${Math.floor(m)} min`:`${Math.floor(m/60)} h ${Math.floor(m%60)} min`;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function persist(next,recovery=false){if(storageError&&!recovery){toast('Primero recupera tus datos en Ajustes.');return false;}try{localStorage.setItem(KEY,JSON.stringify(next));state=next;storageError='';return true;}catch(e){toast('No se pudo guardar. El almacenamiento está lleno o bloqueado. Descarga un respaldo.');return false;}}
function commit(fn){const copy=structuredClone(state);fn(copy);return persist(copy);}
function go(p){if(location.hash===`#${p}`){page=p;render();}else location.hash=p;}
function heading(title,sub,label='OPERACIÓN DIARIA',extra=''){return `<div class="page-heading"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p>${sub}</p></div>${extra}</div>`;}
function stat(label,value,sub,ico,featured=false){return `<div class="stat ${featured?'featured':''}"><div class="stat-label">${label}${icon(ico)}</div><div class="stat-value">${value}</div><div class="stat-sub">${sub}</div></div>`;}
function stats(){const ins=inside(),paid=state.visits.filter(v=>v.status==='paid'&&day(v.paidAt)===today()),out=state.visits.filter(v=>v.exit&&day(v.exit)===today());return `<div class="stats">${stat('Vehículos dentro',`${ins.length}<small> / ${state.settings.capacity}</small>`,`${Math.max(0,state.settings.capacity-ins.length)} espacios disponibles`,'entrada')}${stat('Cobrado hoy',money(paid.reduce((a,v)=>a+v.total,0)),`${paid.length} cobros registrados`,'money',true)}${stat('Entradas de hoy',state.visits.filter(v=>day(v.entry)===today()).length,'Vehículos recibidos','plus')}${stat('Salidas de hoy',out.length,'Vehículos que ya salieron','salida')}</div>`;}
function card(title,ico,body,extra=''){return `<section class="card"><div class="card-head"><div class="title-group"><span class="icon-box">${icon(ico)}</span><h2>${title}</h2></div>${extra}</div>${body}</section>`;}
function empty(title,text,ico='entrada',button=''){return `<div class="empty"><div class="empty-art">${icon(ico)}</div><h3>${title}</h3><p>${text}</p>${button}</div>`;}
function vehicleRow(v){const q=quote(v);return `<div class="vehicle-row"><div class="vehicle-symbol">${icon(v.type)}</div><div class="vehicle-detail"><strong>${esc(v.plate)}</strong><span class="ticket-inline">${ticketNumber(v.ticket)}</span><p>${types[v.type]} · ${time(v.entry)} · ${duration(q.minutes)}</p>${v.keys?`<span class="key-badge">${icon('key')} Dejó llave</span>`:''}</div><div class="row-end"><strong>${money(q.gross)}</strong><div class="vehicle-actions"><button class="button charge-button" data-charge="${esc(v.id)}">Cobrar</button><button class="button outline eye-button" data-receipt="${esc(v.id)}" aria-label="Ver ticket ${ticketNumber(v.ticket)}">${icon('eye')}</button></div></div></div>`;}
function filteredVehicles(){const query=page==='salida'?exitSearch:search;return inside().filter(v=>(page==='salida'||filter==='all'||v.type===filter)&&matchesVehicle(v,query)).sort((a,b)=>b.entry-a.entry);}
function vehicleList(){const list=filteredVehicles();return list.length?list.map(vehicleRow).join(''):empty(inside().length?'Sin coincidencias':'Tu garaje está listo',inside().length?'Prueba con otra placa o número de ticket.':'Registra el primer vehículo. Aquí verás quién está dentro y cuánto lleva.');}
const clockTime=time;
function currentClock(){return `<time class="current-clock" data-current-clock datetime="${new Date().toISOString()}" aria-label="Hora actual">${clockTime(Date.now())}</time>`;}
function updateClocks(){document.querySelectorAll('[data-current-clock]').forEach(el=>{el.textContent=clockTime(Date.now());el.dateTime=new Date().toISOString();});}
setInterval(updateClocks,1000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateClocks();});
function entryPage(){const n=nextFree(state),s=state.settings,remaining=n?s.ticketEnd-n+1-state.visits.filter(v=>v.ticket>=n&&v.status!=='cancelled').length:0;return `<div class="entry-simple"><section class="card folio-card"><div class="folio-top"><span class="small-label">${icon('tickets')} TALONARIO ACTIVO</span><button class="text-button" data-action="adjust-folio">${icon('ajustes')} Ajustar folio</button></div><div class="folio-main"><div><strong>${n?ticketNumber(n):'Agotado'}</strong><span>Siguiente en mano</span></div><span class="pill">${remaining} restantes</span></div><div class="progress"><span style="width:${Math.min(100,state.visits.filter(v=>v.status!=='cancelled').length/s.ticketEnd*100)}%"></span></div><div class="folio-meta"><span>Talonario: 00001 – ${ticketNumber(s.ticketEnd)}</span><button class="text-button skip-link" type="button" data-action="skip-ticket" ${!n||n>=s.ticketEnd?'disabled':''}>Saltar ticket</button></div></section><form id="entry-form"><section class="card entry-fields"><label class="field"><span class="label-row"><span>${icon('tickets')} Placa del vehículo</span>${currentClock()}</span><div class="input-wrap">${icon('entrada')}<input class="plate-input" id="plate" name="plate" placeholder="ABC-123" maxlength="12" autocomplete="off" autocapitalize="characters" spellcheck="false" required aria-label="Placa del vehículo"><button type="button" class="clear" data-action="clear-plate" aria-label="Borrar placa">${icon('close')}</button></div></label><span class="field-label">Tipo de vehículo</span><div class="categories">${Object.keys(types).map(k=>`<button type="button" class="category ${category===k?'selected':''}" data-category="${k}" aria-pressed="${category===k}">${icon(k)}<strong>${types[k]}</strong><small>${money(s.rates[k])} / ${s.block===60?'hora':s.block+' min'}</small></button>`).join('')}</div><label class="key-switch"><span>Dejó llave</span><input type="checkbox" name="keys" id="left-keys" role="switch" aria-label="Dejó llave"></label></section><div id="entry-error"></div><button class="button big wide register-button" ${!n||storageError?'disabled':''}>${icon('tickets')} Registrar ${n?'('+ticketNumber(n)+')':''}</button></form>${recentTickets()}</div>`;}
function exitPage(){return `<div class="exit-simple">${heading('Cobrar','','')}<section class="card"><div class="card-body"><label class="field"><span>Placa o número de ticket</span><div class="input-wrap">${icon('search')}<input id="exit-search" class="plate-input" placeholder="ABC-123 o 00001" value="${esc(exitSearch)}" autocomplete="off" aria-label="Placa o número de ticket"></div></label><button class="button secondary wide" data-action="scan-exit">${icon('qr')} Escanear QR del ticket</button></div><div class="list-heading"><h2>Vehículos dentro</h2><span class="pill">${inside().length}</span></div><div id="exit-list" class="vehicle-list">${vehicleList()}</div></section></div>`;}
function recentTickets(){const recent=state.visits.filter(v=>v.status!=='cancelled').sort((a,b)=>b.entry-a.entry).slice(0,5);return `<section class="card recent-registrations"><div class="card-head"><h2>Últimos tickets registrados</h2><button class="text-button" data-go="historial">Ver todos</button></div>${recent.length?recent.map(v=>`<article class="vehicle-row recent-ticket"><div class="vehicle-detail"><strong>${esc(v.plate)}</strong><p class="recent-number">Ticket ${ticketNumber(v.ticket)}</p><p>Entrada ${clockTime(v.entry)}${day(v.entry)!==today()?' · '+date(v.entry):''}</p></div><div class="row-end">${statusPill(v)}<button class="button outline eye-button" data-receipt="${esc(v.id)}" aria-label="Ver ticket ${ticketNumber(v.ticket)}">${icon('eye')}</button></div></article>`).join(''):empty('Aún no hay tickets','Aquí aparecerán los últimos registros.','tickets')}</section>`;}
function dashboard(){const totals=dayTotals(state),paid=state.visits.filter(v=>v.status==='paid'&&day(v.paidAt)===today()),sum=(vs,key)=>vs.reduce((a,v)=>a+(v[key]||0),0);return `<div class="home-simple">${heading('Inicio',new Date().toLocaleDateString('es-PE',{weekday:'long',day:'numeric',month:'long'}),'')}<div class="home-clock"><span>Hora actual</span>${currentClock()}</div><div class="stats home-stats">${stat('Vehículos dentro',`${totals.inside}<small> / ${state.settings.capacity}</small>`,`${Math.max(0,state.settings.capacity-totals.inside)} espacios libres`,'entrada')}${stat('Cobrado hoy',money(totals.collected),`${totals.paidCount} pagos recibidos`,'money',true)}</div><div class="home-actions"><button class="button big" data-go="entrada">${icon('entrada')} Registrar</button><button class="button big secondary" data-go="salida">${icon('money')} Cobrar</button></div><div class="home-numbers"><div><span>Entradas hoy</span><strong>${totals.entries}</strong></div><div><span>Salidas hoy</span><strong>${totals.exits}</strong></div><div><span>No pagaron</span><strong>${totals.unpaidCount}</strong></div></div><details class="settings-section"><summary>${icon('money')} Detalle de caja<span class="setting-chevron">${icon('chevronDown')}</span></summary><div class="card-body metrics-detail"><div class="detail-line"><span>No cobrado hoy</span><strong>${money(totals.notCollected)}</strong></div><div class="detail-line"><span>Exonerado en salidas de hoy</span><strong>${money(totals.discounts)}</strong></div>${['Efectivo','Yape / Plin','Tarjeta','Transferencia'].map(m=>`<div class="detail-line"><span>${m}</span><strong>${money(sum(paid.filter(v=>v.method===m),'total'))}</strong></div>`).join('')}</div></details>${recentTickets()}</div>`;}
function historyRows(){const q=historySearch,vs=state.visits.filter(v=>(historyStatus==='all'||v.status===historyStatus)&&(!historyDate||day(v.entry)===historyDate||v.exit&&day(v.exit)===historyDate)&&matchesVehicle(v,q)).sort((a,b)=>b.entry-a.entry);return vs.length?`${historyMobile(vs)}<div class="table-wrap"><table><thead><tr><th>VEHÍCULO / TICKET</th><th>ENTRADA</th><th>SALIDA</th><th>BRUTO</th><th>EXONERADO</th><th>IMPORTE</th><th>ESTADO</th><th></th></tr></thead><tbody>${vs.map(v=>`<tr><td><strong>${esc(v.plate)}</strong><small>#${ticketNumber(v.ticket)} · ${types[v.type]}${v.keys?' · Dejó llave':''}</small></td><td>${date(v.entry)}<small>${time(v.entry)}</small></td><td>${v.exit?`${date(v.exit)}<small>${time(v.exit)}</small>`:'—'}</td><td>${v.status==='cancelled'?'—':money(v.exit?v.gross:quote(v).gross)}</td><td>${v.status==='cancelled'?'—':v.exit?money(v.discount):'—'}<small>${esc(v.reason||'')}</small></td><td><strong>${v.status==='cancelled'?'—':v.exit?money(v.total):'—'}</strong><small>${v.status==='unpaid'?'No cobrado':esc(v.method||'')}</small></td><td>${statusPill(v)}</td><td>${v.status==='inside'?`<button class="mini-button" data-charge="${v.id}">Cobrar</button>`:`<button class="text-button" data-receipt="${v.id}">Ver detalle</button>`}</td></tr>`).join('')}</tbody></table></div>`:empty('Sin movimientos para mostrar','Las entradas y salidas quedarán aquí. Prueba también con otros filtros.','historial');}
function historyPage(){return `<button class="back-link" data-go="resumen">${icon('chevronLeft')} Inicio</button>${heading('Historial','','')}<div class="toolbar"><input type="search" id="history-search" placeholder="Placa o ticket" aria-label="Buscar en historial" value="${esc(historySearch)}"><select id="history-status" aria-label="Estado">${[['all','Todos'],['inside','Dentro'],['paid','Pagados'],['unpaid','No pagó'],['cancelled','Anulados']].map(([k,t])=>`<option value="${k}" ${k===historyStatus?'selected':''}>${t}</option>`).join('')}</select><input id="history-date" type="date" aria-label="Fecha de entrada o salida" value="${esc(historyDate)}"><button class="button outline" data-action="clear-history">Limpiar</button></div><div class="card" id="history-results">${historyRows()}</div>`;}
function ticketsPage(){const s=state.settings,n=nextFree(state);return `<button class="back-link" data-go="ajustes">${icon('chevronLeft')} Ajustes</button>${heading('Tickets','','')}<div class="ticket-settings"><section class="card"><div class="card-body"><div class="ticket-status"><span>Del #1 al #${s.ticketEnd}</span><span class="pill">${n?s.ticketEnd-n+1-state.visits.filter(v=>v.ticket>=n&&v.status!=='cancelled').length:0} disponibles</span></div><form id="print-tickets"><h2>Imprimir tickets</h2><div class="form-grid section-gap"><label class="field"><span>Desde</span><input name="from" type="number" min="1" max="${s.ticketEnd}" value="${n||1}" required></label><label class="field"><span>Hasta</span><input name="to" type="number" min="1" max="${s.ticketEnd}" value="${Math.min(s.ticketEnd,(n||1)+49)}" required></label></div><label class="field section-gap"><span>Tickets por hoja A4</span><select name="perPage"><option value="20">20 por hoja</option><option value="15">15 por hoja · más grandes</option><option value="30">30 por hoja · ahorrar papel</option></select></label><label class="qr-switch"><span>${icon('qr')} Incluir código QR</span><input type="checkbox" name="qr" id="print-qr" checked role="switch"></label><button class="button wide">${icon('print')} Ver tickets para imprimir</button><p class="compact-note">Hasta 500 por impresión. También puedes guardar como PDF.</p></form></div></section><div class="ticket-preview-panel"><div class="preview-label">VISTA PREVIA</div><div id="ticket-preview-content">${ticketMarkup(n||1,s.name,true)}</div></div></div><div class="ticket-tools"><details class="settings-section"><summary>${icon('plus')} Generar más tickets<span class="setting-chevron">${icon('chevronDown')}</span></summary><div class="card-body"><form id="ticket-form">${field('Cantidad de tickets nuevos','quantity',1000,'type="number" min="1" max="1000000" step="1" required')}<p class="compact-note">Continuarán desde el #${s.ticketEnd+1}.</p><button class="button wide section-gap">Generar tickets</button></form></div></details><details class="settings-section"><summary>${icon('ajustes')} Ajustar siguiente folio<span class="setting-chevron">${icon('chevronDown')}</span></summary><div class="card-body"><form id="next-ticket-form">${field('Siguiente número','next',n||s.ticketEnd,'type="number" min="1" max="'+s.ticketEnd+'" step="1" required')}<button class="button secondary wide">Guardar folio</button></form></div></details></div>`;}
function field(label,name,value,attrs='',help=''){return `<label class="field"><span>${label}</span><input name="${name}" value="${esc(value)}" ${attrs}>${help?`<small>${help}</small>`:''}</label>`;}
function settingsPage(){const s=state.settings;return `<div class="settings-simple">${heading('Ajustes','','')}<button class="settings-shortcut" data-go="tickets"><span class="icon-box">${icon('tickets')}</span><span><strong>Tickets</strong><small>Generar, imprimir y código QR</small></span><span class="setting-chevron">${icon('chevronRight')}</span></button><details class="settings-section"><summary>${icon('ajustes')} Garaje, tarifas y tolerancia<span class="setting-chevron">${icon('chevronDown')}</span></summary><div class="card-body"><form id="settings-form">${field('Nombre del garaje','name',s.name,'maxlength="60" required')}<div class="form-grid">${field('Capacidad','capacity',s.capacity,'type="number" min="1" max="100000" step="1" required')}<label class="field"><span>Moneda</span><select name="currency">${['S/','$','€','Bs'].map(c=>`<option ${s.currency===c?'selected':''}>${c}</option>`).join('')}</select></label></div><h3 class="section-title section-gap">Tarifa por bloque</h3>${Object.keys(types).map(k=>field(types[k],k,s.rates[k],'type="number" min="0.01" max="100000" step="0.01" required')).join('')}<div class="form-grid"><label class="field"><span>Cobrar por</span><select name="block">${[60,30,15].map(b=>`<option value="${b}" ${s.block===b?'selected':''}>${b===60?'Hora iniciada':b+' min iniciados'}</option>`).join('')}</select></label>${field('Tolerancia (min)','tolerance',s.tolerance,'type="number" min="0" max="59" step="1" required')}</div><details class="rate-help"><summary>¿Cómo se aplica la tolerancia?</summary><p class="compact-note">Los primeros minutos de tolerancia son gratis. Al superar un bloque, se permite la misma tolerancia. Con S/ 5 por hora y 10 min: 1 h 10 min cuesta S/ 5; 1 h 11 min cuesta S/ 10.</p></details><p class="compact-note">Los cambios se aplican a nuevas entradas.</p><div id="settings-error"></div><button class="button wide section-gap">Guardar ajustes</button></form></div></details><details class="settings-section"><summary>${icon('download')} Datos y respaldo<span class="setting-chevron">${icon('chevronDown')}</span></summary><div class="card-body"><div class="data-actions"><button class="button secondary wide" data-action="backup">${icon('download')} Descargar copia completa</button><button class="button outline wide" data-action="csv">${icon('download')} Exportar CSV</button><label class="button outline wide" for="import-file">${icon('upload')} Importar copia o CSV</label><input id="import-file" type="file" accept=".json,.csv,application/json,text/csv" class="sr-only"></div><p class="compact-note">Para cambiar de celular, descarga una copia e impórtala en el otro. Los dispositivos no se sincronizan.</p><p class="compact-note">Última copia: ${state.backupAt?`${date(state.backupAt)} · ${time(state.backupAt)}`:'todavía no descargada'}.</p>${storageError?'<button class="button danger wide section-gap" data-action="recovery">Recuperar datos originales</button>':''}</div></details><details class="settings-section"><summary>${icon('shield')} Usar sin internet<span class="setting-chevron">${icon('chevronDown')}</span></summary><div class="card-body"><p id="offline-status" class="compact-note">Preparando disponibilidad sin conexión…</p>${isLocalFile?'<p class="compact-note">Este archivo funciona sin conexión, pero no se instala como app en Android. Para instalar, abre el enlace en Chrome con internet.</p><a class="button secondary wide section-gap" href="https://mariosc21.github.io/autobox-garaje/" target="_blank" rel="noopener">Abrir versión para instalar</a>':'<button id="install-app-button" class="button secondary wide section-gap" data-action="install">Instalar AutoBox</button><p class="compact-note">En Android: abre esta web en Chrome → menú ⋮ → Agregar a pantalla principal → Instalar. Espera «Disponible sin conexión» antes de desconectarte.</p>'}<a class="button outline wide section-gap" href="${isLocalFile?esc(location.href):'./AutoBox-portatil.html'}" download="AutoBox.html">Descargar versión portátil</a><p class="compact-note">Guarda un respaldo antes de borrar los datos del navegador.</p></div></details></div>`;}
function render(){const pages={entrada:entryPage,salida:exitPage,resumen:dashboard,historial:historyPage,tickets:ticketsPage,ajustes:settingsPage};if(!pages[page])page='entrada';const selected=page==='tickets'?'ajustes':page==='historial'?'resumen':page;$('#mobile-nav').innerHTML=navItems.map(([k,t])=>`<a href="#${k}" class="${selected===k?'active':''}" ${selected===k?'aria-current="page"':''}>${icon(k==='salida'?'money':k)}<span>${t}</span></a>`).join('');document.title=state.settings.name+' · '+({resumen:'Inicio',entrada:'Registrar',salida:'Cobrar',historial:'Historial',tickets:'Tickets',ajustes:'Ajustes'})[page];$('#main').innerHTML=(storageError?`<div class="error">${storageError}</div>`:'')+pages[page]();connectivity();syncInstallUI();}
function errorAt(id,message){const el=$(id);if(el)el.innerHTML=`<div class="error" role="alert">${esc(message)}</div>`;else toast(message);}
function showDialog(title,body){$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button data-action="close-dialog" aria-label="Cerrar">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!$('#dialog').open)$('#dialog').showModal();}
let charge=null;
function chargeDialog(id){const v=state.visits.find(v=>v.id===id);if(!v||v.exit)return;const exit=Date.now(),q=quote(v,exit);charge={id,exit,...q};showDialog('Cobrar',`<div class="dialog-plate"><div><strong>${esc(v.plate)}</strong><p>${types[v.type]} · Ticket ${ticketNumber(v.ticket)}</p></div><span class="pill">${duration(q.minutes)}</span></div><div class="metrics-detail"><div class="detail-line"><span>Entrada</span><strong>${date(v.entry)} · ${time(v.entry)}</strong></div><div class="detail-line"><span>Salida</span><strong>${date(exit)} · ${time(exit)}</strong></div><div class="detail-line"><span>Dejó llave</span><strong class="${v.keys?'has-key':''}">${v.keys?'Sí':'No'}</strong></div><div class="detail-line"><span>Tarifa de esta entrada</span><strong>${money(v.rate)} / ${v.block} min</strong></div><div class="detail-line"><span>Tolerancia</span><strong>${v.tolerance} minutos</strong></div><div class="detail-line"><span>${q.blocks} ${q.blocks===1?'bloque cobrado':'bloques cobrados'}</span><strong>${money(q.gross)}</strong></div></div><form id="charge-form"><div class="waive-options"><button type="button" class="button secondary" data-action="waive-fraction" ${q.blocks<2?'disabled':''}>Perdonar última fracción</button><button type="button" class="button outline" data-action="manual-discount">Otro descuento</button></div><div id="discount-area" class="discount-area" hidden><label class="field"><span>Monto a exonerar (${esc(state.settings.currency)})</span><input id="discount" type="number" min="0" max="${q.gross}" step="0.01" value="0"></label><label class="field"><span>Motivo de la exoneración</span><input id="discount-reason" maxlength="300" placeholder="Ej. Cortesía por 5 minutos extra"></label></div><div class="charge-hero"><span id="charge-amount-label">TOTAL A COBRAR</span><strong id="charge-total">${money(q.gross)}</strong><small id="discount-summary">Sin exoneración</small></div><label class="field"><span>Medio de pago</span><select id="payment-method">${['Efectivo','Yape / Plin','Tarjeta','Transferencia'].map(m=>`<option>${m}</option>`).join('')}</select></label><div class="status-choice"><label><input name="payment-status" type="radio" value="paid" checked> Ya pagó</label><label><input name="payment-status" type="radio" value="unpaid"> No pagó</label></div><p id="no-pay-note" class="compact-note" hidden>La salida se cierra sin dejar una deuda pendiente.</p><div id="charge-error"></div><button class="button big wide section-gap">${icon('check')} <span id="charge-submit-label">Cobrar</span></button></form><button class="button outline wide section-gap cancel-link" data-cancel="${v.id}">Anular registro</button>`);}
function updateDiscount(){const discount=Number($('#discount').value);$('#charge-total').innerHTML=money(Math.max(0,charge.gross-(Number.isFinite(discount)?discount:0)));$('#discount-summary').textContent=discount>0?`Exoneración: ${state.settings.currency} ${discount.toFixed(2)}`:'Sin exoneración';}
function receipt(id){const v=state.visits.find(v=>v.id===id);if(!v)return;showDialog('Detalle del ticket',`<div class="ticket-detail-title"><strong>${esc(v.plate)}</strong><p>Ticket ${ticketNumber(v.ticket)} · ${types[v.type]}</p>${statusPill(v)}</div><div class="metrics-detail"><div class="detail-line"><span>Dejó llave</span><strong class="${v.keys?'has-key':''}">${v.keys?'Sí':'No'}</strong></div><div class="detail-line"><span>Entrada</span><strong>${date(v.entry)} · ${time(v.entry)}</strong></div>${v.status==='cancelled'?`<div class="detail-line"><span>Anulado</span><strong>${date(v.exit)} · ${time(v.exit)}</strong></div><p class="compact-note">No se entregó el boleto. El registro no cuenta como entrada, salida ni cobro. El número puede volver a utilizarse.</p>`:v.exit?`<div class="detail-line"><span>Salida</span><strong>${date(v.exit)} · ${time(v.exit)}</strong></div><div class="detail-line"><span>Estancia</span><strong>${duration((v.exit-v.entry)/60000)}</strong></div><div class="detail-line"><span>Importe original</span><strong>${money(v.gross)}</strong></div><div class="detail-line"><span>Exonerado</span><strong>${money(v.discount)}</strong></div>${v.reason?`<div class="notice">${icon('info')}<div><strong>Motivo</strong>${esc(v.reason)}</div></div>`:''}<div class="detail-line total"><span>${v.status==='unpaid'?'No cobrado':'Total'}</span><strong>${money(v.total)}</strong></div>${v.status==='paid'?`<div class="detail-line"><span>Medio de pago</span><strong>${esc(v.method)}</strong></div><div class="detail-line"><span>Pago registrado</span><strong>${date(v.paidAt)} · ${time(v.paidAt)}</strong></div>`:'<p class="compact-note">La salida quedó cerrada sin pago. No queda una deuda pendiente.</p>'}`:`<div class="detail-line"><span>Tarifa</span><strong>${money(v.rate)} / ${v.block} min</strong></div>`}</div>${v.status==='inside'?`<button class="button outline wide section-gap cancel-link" data-cancel="${v.id}">Anular registro</button>`:''}`);}
function download(name,content,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function backup(csv=false){const next=structuredClone(state);next.backupAt=Date.now();download(`AutoBox-${today()}-${time(Date.now()).replace(':','-')}.${csv?'csv':'json'}`,csv?toCSV(next):JSON.stringify(next,null,2),csv?'text/csv;charset=utf-8':'application/json');persist(next);toast('Copia descargada. Guárdala fuera de este dispositivo.');if(page==='ajustes')render();}
function printDocument(content,title,extraStyles=''){const frame=document.createElement('iframe');frame.className='print-frame';frame.title='Vista de impresión';frame.style.cssText='position:fixed;left:-9999px;width:1px;height:1px';document.body.append(frame);frame.srcdoc=`<!doctype html><html lang="es"><head><meta charset="utf-8"><title>${esc(title)}</title><style>body{font:14px Arial;color:#222;margin:24px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}h1{font-size:20px}p{line-height:1.8}.receipt{max-width:340px;margin:auto;border:1px dashed #aaa;padding:25px}@media print{@page{size:A4;margin:10mm}body{margin:0}}${ticketStyles}${extraStyles}</style></head><body>${content}</body></html>`;frame.onload=()=>setTimeout(()=>{frame.contentWindow.focus();frame.contentWindow.print();},150);setTimeout(()=>frame.remove(),180000);}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.go){go(b.dataset.go);return;}if(b.dataset.category){category=b.dataset.category;document.querySelectorAll('.category').forEach(x=>{x.classList.toggle('selected',x.dataset.category===category);x.setAttribute('aria-pressed',String(x.dataset.category===category));});return;}if(b.dataset.filter){filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x.dataset.filter===filter));$('#vehicle-list').innerHTML=vehicleList();return;}if(b.dataset.charge){chargeDialog(b.dataset.charge);return;}if(b.dataset.receipt){receipt(b.dataset.receipt);return;}if(b.dataset.cancel){cancelDialog(b.dataset.cancel);return;}
 switch(b.dataset.action){case 'confirm-cancel':{const id=b.dataset.id;try{const next=cancelRegistration(state,id);if(persist(next)){$('#dialog').close();lastEntry=null;render();toast('Registro anulado. El boleto vuelve a estar disponible.');}}catch(error){toast(error.message);}break;}case 'skip-ticket':skipTicketDialog();break;case 'scan-exit':scanTicket('exit');break;case 'scan-entry':scanTicket('entry');break;case 'adjust-folio':adjustFolio();break;case 'print-range':printDocument(ticketPrintContent,'AutoBox · Tickets');break;case 'clear-plate':$('#plate').value='';$('#plate').focus();break;case 'backup':backup();break;case 'csv':backup(true);break;case 'close-dialog':$('#dialog').close();break;case 'manual-discount':$('#discount-area').hidden=false;$('#discount').focus();break;case 'waive-fraction':{const v=state.visits.find(v=>v.id===charge.id);$('#discount-area').hidden=false;$('#discount').value=v.rate;$('#discount-reason').value='Cortesía: última fracción exonerada';updateDiscount();break;}case 'clear-history':historySearch='';historyStatus='all';historyDate='';render();break;case 'confirm-import':{if(!pendingImport)return;const prior=state;if(storageError)download('AutoBox-recuperacion-previa.txt',localStorage.getItem(KEY)||'Sin datos','text/plain');download(`AutoBox-antes-de-importar-${today()}.json`,JSON.stringify(prior,null,2),'application/json');if(persist(pendingImport,true)){pendingImport=null;lastEntry=null;$('#dialog').close();render();toast('Datos importados. Ya puedes continuar.');}break;}case 'recovery':try{download('AutoBox-recuperacion.txt',localStorage.getItem(KEY)||'Sin datos','text/plain');}catch{toast('El navegador no permite leer el almacenamiento.');}break;case 'install':installAutoBox();break;case 'install-help':showDialog('Instalar AutoBox',`<p>En <strong>Android</strong>, abre el menú del navegador y elige «Instalar aplicación» o «Agregar a pantalla de inicio».</p><p class="section-gap">En <strong>iPhone</strong>, abre en Safari, toca Compartir y luego «Añadir a pantalla de inicio».</p><div class="notice">${icon('info')}<div>Abre la app una vez con internet y espera «Disponible sin conexión» antes de desconectarte. Guarda un respaldo para pasar los datos a otro equipo.</div></div>`);break;}
});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='plate'){const prev=t.value,pos=t.selectionStart,next=formatPlate(prev);if(next!==prev){t.value=next;const caret=Math.max(0,(pos??prev.length)+next.length-prev.length);t.setSelectionRange(caret,caret);}}if(t.id==='vehicle-search'){search=t.value;$('#vehicle-list').innerHTML=vehicleList();}if(t.id==='exit-search'){exitSearch=t.value;$('#exit-list').innerHTML=vehicleList();}if(t.id==='history-search'){historySearch=t.value;$('#history-results').innerHTML=historyRows();}if(t.id==='discount')updateDiscount();});
document.addEventListener('change',async e=>{if(e.target.id==='history-status'){historyStatus=e.target.value;$('#history-results').innerHTML=historyRows();}if(e.target.id==='history-date'){historyDate=e.target.value;$('#history-results').innerHTML=historyRows();}if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;try{if(file.size>30*1024*1024)throw Error('El archivo supera 30 MB.');const text=await file.text();pendingImport=file.name.toLowerCase().endsWith('.csv')?fromCSV(text):validate(JSON.parse(text));const ins=pendingImport.visits.filter(v=>!v.exit).length;showDialog('Revisar importación',`<p>Archivo: <strong>${esc(file.name)}</strong></p><div class="metrics-detail section-gap"><div class="detail-line"><span>Garaje</span><strong>${esc(pendingImport.settings.name)}</strong></div><div class="detail-line"><span>Movimientos</span><strong>${pendingImport.visits.length}</strong></div><div class="detail-line"><span>Vehículos dentro</span><strong>${ins}</strong></div><div class="detail-line"><span>Tickets generados</span><strong>${pendingImport.settings.ticketEnd}</strong></div></div><div class="notice warn">${icon('info')}<div><strong>Se reemplazarán los datos actuales</strong>Actualmente tienes ${state.visits.length} movimientos. Se descargará una copia de tus datos actuales antes de importar. Los registros no se mezclan.</div></div><button class="button wide section-gap" data-action="confirm-import">Reemplazar e importar copia</button>`);}catch(error){pendingImport=null;toast('No se importó: '+error.message);}e.target.value='';}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,f=new FormData(form);if(form.id==='entry-form'){const plate=String(f.get('plate')).trim().toUpperCase(),n=nextFree(state);if(!/^[A-Z0-9-]{3,12}$/.test(plate)||normalizePlate(plate).length<3){errorAt('#entry-error','Ingresa una placa válida de 3 a 12 caracteres.');return;}if(inside().some(v=>normalizePlate(v.plate)===normalizePlate(plate))){errorAt('#entry-error','Esa placa ya está dentro. Revisa su ticket en Cobrar.');return;}if(inside().length>=state.settings.capacity){errorAt('#entry-error','El garaje está lleno. Registra una salida o ajusta la capacidad.');return;}if(!n){toast('Genera más tickets en Talonario.');return;}const s=state.settings,v={id:globalThis.crypto?.randomUUID?.()||`v-${Date.now()}-${Math.random().toString(36).slice(2)}`,ticket:n,plate,type:category,keys:f.get('keys')==='on',entry:Date.now(),exit:null,rate:s.rates[category],tolerance:s.tolerance,block:s.block,status:'inside'};if(commit(x=>{x.visits.push(v);x.settings.nextTicket=n+1;})){document.activeElement?.blur();lastEntry=v;render();toast(`Registro guardado · ${plate} · Ticket #${n}`);}}
 if(form.id==='charge-form'){const v=state.visits.find(v=>v.id===charge.id);if(!v||v.exit){errorAt('#charge-error','Esta salida ya fue registrada.');return;}const discount=Number($('#discount').value),reason=$('#discount-reason').value.trim(),status=f.get('payment-status'),method=status==='paid'?$('#payment-method').value:'';if(!Number.isFinite(discount)||discount<0||discount>charge.gross){errorAt('#charge-error','La exoneración debe estar entre cero y el importe original.');return;}if(discount>0&&!reason){errorAt('#charge-error','Escribe el motivo de la exoneración para que quede registrado.');return;}if(commit(x=>Object.assign(x.visits.find(v=>v.id===charge.id),{exit:charge.exit,gross:charge.gross,discount:Math.round(discount*100)/100,reason:discount>0?reason:'',total:Math.round((charge.gross-discount)*100)/100,status,method,paidAt:status==='paid'?Date.now():null}))){$('#dialog').close();lastEntry=null;render();toast(status==='paid'?'Pago y salida registrados.':'Salida cerrada: No pagó.');}}
 if(form.id==='settings-form'){const s={...state.settings,name:String(f.get('name')).trim(),capacity:+f.get('capacity'),currency:f.get('currency'),rates:Object.fromEntries(Object.keys(types).map(k=>[k,+f.get(k)])),block:+f.get('block'),tolerance:+f.get('tolerance')};try{if(!s.name)throw Error('Escribe el nombre de tu garaje.');if(s.currency!==state.settings.currency&&state.visits.length)throw Error('Con movimientos registrados, conserva la moneda actual para no mezclar los importes del historial.');validate({...state,settings:s});if(persist({...state,settings:s})){render();toast('Ajustes guardados para las próximas entradas.');}}catch(error){errorAt('#settings-error',error.message);}}
 if(form.id==='ticket-form'){const qty=+f.get('quantity');if(!Number.isInteger(qty)||qty<1||qty>1000000||state.settings.ticketEnd+qty>10000000){toast('Introduce una cantidad entera válida; máximo total: 10 millones.');return;}if(commit(x=>x.settings.ticketEnd+=qty)){render();toast(`${qty} tickets nuevos generados.`);}}
 if(form.id==='next-ticket-form'){const n=+f.get('next');if(!Number.isInteger(n)||n<1||n>state.settings.ticketEnd){toast('El número debe estar dentro del talonario.');return;}if(commit(x=>x.settings.nextTicket=n)){render();toast('Siguiente número ajustado.');}}
 if(form.id==='print-tickets'){previewPrintTickets(f);}
 if(form.id==='skip-form'){const current=nextFree(state),n=+f.get('next');if(!current||!Number.isInteger(n)||n<=current||n>state.settings.ticketEnd){errorAt('#skip-error','Elige un número mayor al actual y dentro del talonario.');return;}if(state.visits.some(v=>v.ticket===n&&v.status!=='cancelled')){errorAt('#skip-error','Ese ticket ya fue utilizado. Elige otro.');return;}if(commit(x=>x.settings.nextTicket=n)){$('#dialog').close();render();toast('Continuar desde el ticket '+ticketNumber(n)+'. No se registró ningún vehículo.');}}
 if(form.id==='folio-form'){const n=+f.get('next');if(!Number.isInteger(n)||n<1||n>state.settings.ticketEnd){errorAt('#folio-error','Elige un número del talonario.');return;}if(state.visits.some(v=>v.ticket===n&&v.status!=='cancelled')){errorAt('#folio-error','Ese ticket ya fue utilizado. Elige otro.');return;}if(commit(x=>x.settings.nextTicket=n)){$('#dialog').close();render();toast('Siguiente ticket: '+ticketNumber(n));}}

});
let offlineReady=false;function connectivity(){const el=$('#connectivity');if(el)el.innerHTML=`<span class="dot"></span> ${isLocalFile?'Versión portátil':offlineReady?'Disponible sin conexión':navigator.onLine?'En este dispositivo':'Sin conexión'}`;const status=$('#offline-status');if(status)status.textContent=isLocalFile?'Versión portátil guardada en este archivo.':offlineReady?'Disponible sin conexión. Ya puedes abrirla sin internet.':'Preparando disponibilidad sin conexión…';}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1);render();window.scrollTo(0,0);});window.addEventListener('online',connectivity);window.addEventListener('offline',connectivity);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;syncInstallUI();});window.addEventListener('appinstalled',()=>{installEvent=null;syncInstallUI();toast('AutoBox instalada. Puedes abrirla desde su icono.');});
window.addEventListener('storage',e=>{if(e.key===KEY){try{state=validate(JSON.parse(e.newValue));storageError='';lastEntry=null;$('#dialog').close();render();toast('Datos actualizados desde otra pestaña.');}catch{toast('Los datos cambiaron en otra pestaña. Recarga antes de continuar.');}}});
let ticketPrintContent='',scanCleanup=null;
function adjustFolio(){const n=nextFree(state);showDialog('Siguiente ticket',`<form id="folio-form">${field('Número del boleto en mano','next',n||1,'type="number" min="1" max="'+state.settings.ticketEnd+'" step="1" required')}<div id="folio-error"></div><button class="button wide">Usar este ticket</button><button class="button outline wide section-gap" type="button" data-action="scan-entry">${icon('qr')} Escanear QR del boleto</button></form>`);}
function scanTicket(mode){scanCleanup?.();showDialog('Escanear ticket',scannerMarkup);scanCleanup=mountScanner($('#dialog'),raw=>{const number=parseTicketCode(raw);if(!number)throw Error('Este QR no es un ticket de AutoBox.');if(mode==='entry'){if(number>state.settings.ticketEnd)throw Error('Este número todavía no está generado. Agrégalo en Ajustes → Tickets.');if(state.visits.some(v=>v.ticket===number&&v.status!=='cancelled'))throw Error('Este ticket ya fue utilizado. Usa otro boleto.');if(!commit(x=>x.settings.nextTicket=number))return false;$('#dialog').close();render();$('#plate')?.focus();toast('Ticket '+ticketNumber(number)+' seleccionado.');}else{const v=state.visits.find(v=>v.ticket===number&&v.exit==null);if(!v){const used=state.visits.find(v=>v.ticket===number&&v.status!=='cancelled');throw Error(used?'Este ticket ya tiene una salida registrada.':'No hay un vehículo dentro con ese ticket.');}$('#dialog').close();exitSearch=String(number);if(page==='salida')render();chargeDialog(v.id);}return true;});}
function previewPrintTickets(formData){const from=+formData.get('from'),to=+formData.get('to'),withQR=formData.get('qr')==='on',perPage=+formData.get('perPage');if(to>state.settings.ticketEnd){toast('El rango supera los tickets generados.');return;}try{ticketPrintContent=ticketSheets(from,to,state.settings.name,withQR,perPage);}catch(error){toast(error.message);return;}const count=to-from+1,pages=Math.ceil(count/perPage);showDialog('Tickets para imprimir',`<div class="print-preview-info"><span>${count} tickets · ${pages} ${pages===1?'hoja':'hojas'} A4<br><small>${perPage} por hoja · ${ticketNumber(from)} al ${ticketNumber(to)}</small></span><span class="pill">${withQR?'Con QR':'Sin QR'}</span></div><div class="print-ticket-preview">${ticketMarkup(from,state.settings.name,withQR)}</div><button class="button wide section-gap" data-action="print-range">${icon('print')} Imprimir / Guardar PDF</button>`);}
document.addEventListener('change',e=>{if(e.target.id==='print-qr'){$('#ticket-preview-content').innerHTML=ticketMarkup(+$('#print-tickets [name="from"]').value||1,state.settings.name,e.target.checked);}});
document.addEventListener('input',e=>{if(e.target.closest('#print-tickets')&&e.target.name==='from'){const n=+e.target.value;if(Number.isInteger(n)&&n>0&&n<=10000000)$('#ticket-preview-content').innerHTML=ticketMarkup(n,state.settings.name,$('#print-qr').checked);}});
function skipTicketDialog(){const n=nextFree(state);if(!n||n>=state.settings.ticketEnd){toast('Genera más tickets en Ajustes → Tickets.');return;}showDialog('Saltar ticket',`<p>Ticket actual: <strong>${ticketNumber(n)}</strong></p><form id="skip-form" class="section-gap">${field('Continuar desde el ticket','next',n+1,'type="number" min="'+(n+1)+'" max="'+state.settings.ticketEnd+'" step="1" required')}<p class="compact-note">Se cambia el siguiente número. No se registra ningún vehículo.</p><div id="skip-error"></div><button class="button wide section-gap">Saltar y continuar</button></form>`);}
render();
if('serviceWorker' in navigator&&!isLocalFile){
 const hadController=!!navigator.serviceWorker.controller;
 navigator.serviceWorker.addEventListener('controllerchange',()=>{if(hadController)location.reload();});
 navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(async registration=>{registration.update().catch(()=>{});await navigator.serviceWorker.ready;offlineReady=!!(await caches.match(new URL('./index.html',location.href)));connectivity();}).catch(()=>{const status=$('#offline-status');if(status)status.textContent='No se pudo preparar el modo sin conexión. Abre la web con internet y vuelve a intentarlo.';});
}
setInterval(()=>{if($('#dialog').open)return;if(page==='entrada'&&$('#vehicle-list'))$('#vehicle-list').innerHTML=vehicleList();if(page==='salida'&&$('#exit-list'))$('#exit-list').innerHTML=vehicleList();},30000);
function historyMobile(vs){return `<div class="history-mobile">${vs.map(v=>`<article class="history-item"><div class="history-item-top"><div><strong>${esc(v.plate)}</strong><small>#${ticketNumber(v.ticket)} · ${types[v.type]}${v.keys?' · Dejó llave':''}</small></div>${statusPill(v)}</div><div class="history-times"><span>Entrada<strong>${date(v.entry)} · ${time(v.entry)}</strong></span><span>${v.status==='cancelled'?'Anulado':'Salida'}<strong>${v.exit?`${date(v.exit)} · ${time(v.exit)}`:'En el garaje'}</strong></span></div>${v.discount>0?`<div class="history-discount">Exonerado: ${money(v.discount)}<small>${esc(v.reason)}</small></div>`:''}<div class="history-item-bottom"><div><span>${v.status==='cancelled'?'Registro anulado':v.status==='unpaid'?'No cobrado':v.exit?'Total':'Estimado actual'}</span><strong>${v.status==='cancelled'?'Sin cobro':money(v.exit?v.total:quote(v).gross)}</strong></div>${v.status==='inside'?`<button class="button secondary" data-charge="${v.id}">Cobrar</button>`:`<button class="button outline" data-receipt="${v.id}">Ver detalle</button>`}</div></article>`).join('')}</div>`;}






document.addEventListener('change',e=>{if(e.target.name==='payment-status'&&$('#charge-submit-label')){const unpaid=e.target.value==='unpaid';$('#charge-submit-label').textContent=unpaid?'Cerrar sin pago':'Cobrar';$('#payment-method').disabled=unpaid;$('#payment-method').closest('label').hidden=unpaid;$('#charge-amount-label').textContent=unpaid?'MONTO NO COBRADO':'TOTAL A COBRAR';$('#no-pay-note').hidden=!unpaid;}});


function statusPill(v){return `<span class="pill ${v.status==='paid'?'green':v.status==='unpaid'?'orange':''}">${{inside:'Dentro',paid:'Pagado',unpaid:'No pagó',cancelled:'Anulado'}[v.status]}</span>`;}
function cancelDialog(id){const v=state.visits.find(v=>v.id===id);if(!v||v.status!=='inside')return;showDialog('Anular registro',`<div class="ticket-detail-title"><strong>${esc(v.plate)}</strong><p>Ticket ${ticketNumber(v.ticket)}</p></div><p class="cancel-explanation">Para cuando el auto se retira y todavía no entregaste el boleto físico.</p><p class="compact-note">Se libera la placa, no se registra un cobro y el ticket vuelve a estar disponible.</p><button class="button wide section-gap" data-action="confirm-cancel" data-id="${v.id}">Anular registro sin cobro</button>`);}

function syncInstallUI(){const button=$('#install-app-button');if(!button)return;const installed=window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;button.textContent=installed?'AutoBox ya está instalada':installEvent?'Instalar AutoBox':'Cómo instalar en Android';button.disabled=installed;}
async function installAutoBox(){if(installEvent){const event=installEvent;installEvent=null;try{await event.prompt();const choice=await event.userChoice;if(choice.outcome!=='accepted')toast('Puedes instalarla después desde el menú de Chrome.');}catch{toast('Abre el menú de Chrome y elige Agregar a pantalla principal.');}syncInstallUI();return;}showDialog('Instalar en Android',`<p>Abre este enlace directamente en <strong>Chrome</strong> con internet.</p><p class="section-gap">Toca <strong>⋮ → Agregar a pantalla principal → Instalar</strong>.</p><p class="section-gap">Si aparece «Abrir en AutoBox», ya está instalada. Si estás dentro de WhatsApp, usa «Abrir en Chrome».</p><p class="compact-note section-gap">Cuando indique «Disponible sin conexión», puedes abrirla desde su icono sin internet.</p>`);}
